/* Demonstrates creating, setting, and then immediately retrieving the state of a timerfd. */
#include <sys/timerfd.h>
#include <time.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>

#define handle_error(msg) \
    do { perror(msg); exit(EXIT_FAILURE); } while (0)

int main(void)
{
    struct itimerspec set_spec, get_spec;
    int tfd;

    /* 1. Create the timer file descriptor using a monotonic clock */
    tfd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (tfd == -1) {
        handle_error("timerfd_create");
    }

    /* 2. Define the timer settings: 5 seconds initial delay, 0 recurrence */
    set_spec.it_interval.tv_sec = 0;   
    set_spec.it_interval.tv_nsec = 0;
    set_spec.it_value.tv_sec = 5;
    set_spec.it_value.tv_nsec = 0;

    /* 3. Set the timer (relative timing) */
    if (timerfd_settime(tfd, 0, &set_spec, NULL) == -1) {
        close(tfd);
        handle_error("timerfd_settime");
    }

    printf("Timer set for 5 seconds relative time.\n");

    /* 4. Get the current remaining time immediately */
    if (timerfd_gettime(tfd, &get_spec) == -1) {
        close(tfd);
        handle_error("timerfd_gettime");
    }

    /* 5. Display retrieved values */
    printf("--- Timer Status Retrieval ---\n");
    printf("Time remaining (it_value): %ld seconds, %ld nanoseconds\n", 
           (long)get_spec.it_value.tv_sec, (long)get_spec.it_value.tv_nsec);
    printf("Recurrence interval (it_interval): %ld seconds, %ld nanoseconds\n", 
           (long)get_spec.it_interval.tv_sec, (long)get_spec.it_interval.tv_nsec);

    close(tfd);
    return EXIT_SUCCESS;
}
